    "freejt7",
    "copilot",
    "agent",
    "skills",
    "automation"
  ],
  "activationEvents": [
    "onStartupFinished"
  ],
  "main": "./dist/extension.cjs",
  "contributes": {
    "themes": [
      {
        "label": "Free JT7 - Alto Contraste Oscuro",
        "uiTheme": "vs-dark",
        "path": "./themes/high-contrast-dark.json"
