# Frontmatter
# â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

def parse_frontmatter(text: str) -> tuple[dict, str]:
    """Parsea frontmatter YAML simple (solo primer nivel + metadata: bloque)."""
    pattern = re.compile(r'^---\s*\n(.*?)\n---\s*\n', re.DOTALL)
    m = pattern.match(text)
    if not m:
        return {}, text
    meta: dict[str, Any] = {}
    lines = m.group(1).splitlines()
    i = 0
    while i < len(lines):
        line = lines[i]
        if not line.strip() or line.startswith('#'):
            i += 1
            continue
        if re.match(r'^[a-zA-Z0-9_-]+:\s*$', line):
            # bloque anidado
            key = line.split(':')[0].strip()
            sub: dict[str, Any] = {}
            i += 1
            while i < len(lines) and (lines[i].startswith('  ') or lines[i].startswith('\t')):
                sub_line = lines[i].strip()
                if ':' in sub_line:
                    sk, _, sv = sub_line.partition(':')
                    sv = sv.strip().strip('"')
                    # parse list
                    if sv.startswith('[') and sv.endswith(']'):
                        sv = [x.strip().strip('"') for x in sv[1:-1].split(',') if x.strip()]
                    sub[sk.strip()] = sv
                i += 1
            meta[key] = sub
        elif ':' in line:
            k, _, v = line.partition(':')
            v = v.strip().strip('"')
            if v.startswith('[') and v.endswith(']'):
                v = [x.strip().strip('"') for x in v[1:-1].split(',') if x.strip()]
            meta[k.strip()] = v
            i += 1
        else:
            i += 1
            continue
    return meta, text[m.end():]


def build_frontmatter(meta: dict, body: str) -> str:
    """Serializa frontmatter dict a YAML block + cuerpo."""
    lines = ["---"]
    for k, v in meta.items():
        if isinstance(v, dict):
            lines.append(f"{k}:")
            for sk, sv in v.items():
                if isinstance(sv, list):
                    lines.append(f"  {sk}: [{', '.join(sv)}]")
                else:
                    lines.append(f"  {sk}: {sv}")
        elif isinstance(v, list):
            lines.append(f"{k}: [{', '.join(str(x) for x in v)}]")
        else:
            lines.append(f"{k}: {v}")
    lines.append("---")
    lines.append("")
    return "\n".join(lines) + body


